  "anomaly_detected": true,
  "confidence": 0.4,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["J2", "U1", "U4"],
      "pins": ["J2.4", "U1.1", "U4.1"],
      "nets": ["NET0004"],
      "obs": "The I2C header J2 pin 4 is wired to NET0004, the same net that is the MCU RESET/PB5 pin (U1.1 / U4.1), the ISP RST line (J8.3) and the reset pull-up R2.",
      "exp": "A 4/5-pin I2C header's non-power pins should carry SDA/SCL (and, if present, an interrupt/ALERT line on a normal GPIO); the MCU RESET pin is an input-only pin with a pull-up and is also the ISP programming reset, so it must not be exposed to / driven by an external I2C device. The 4th header pin should be a separate net (e.g. an interrupt on a spare GPIO), not NET0004.",
      "evidence": [
        {"source": "schematic", "quote": "J2 (I2C) pin4 -> NET0004; U1 pin1 RESET/PB5 -> NET0004; J8 AVR-ISP-6 pin3 RST -> NET0004; R2 10K -> NET0004 (sheet /, page 1)"},
        {"source": "spec", "quote": "an ATtiny-driven fan controller (Atmel category)"}
      ],
      "impact": "Any external I2C device that asserts that header line (e.g. an active-low interrupt) would pull the MCU reset low and repeatedly reset the controller; conversely the reset pull-up/ISP activity is exposed on the connector. The board would not behave as a normal I2C interface.",
      "confidence": 0.45
    },
    {
      "category": "wrong_value",
      "components": ["C1", "U3"],
      "pins": ["U3.2"],
      "nets": ["+5V"],
      "obs": "The LM1117-5.0 output (+5V rail) is bypassed with only C1 = 100 nF; no larger output capacitor is shown.",
      "exp": "The LM1117 datasheet requires an output capacitor of roughly 10 uF or larger for loop stability; 100 nF is far too small and the regulator can oscillate.",
      "evidence": [
        {"source": "schematic", "quote": "U3 LM1117-5.0, VO -> +5V, C1 100nF (sheet /, page 1 right column)"}
      ],
      "impact": "Possible LDO oscillation / unstable +5V rail feeding the MCU and ISP/I2C connectors.",
      "confidence": 0.3
    }
  ],
  "summary": "The digital section (ISP mapping, dual ATtiny footprints, potentiometer ADC, rails) is internally consistent, but the I2C header's 4th pin is tied to the MCU RESET net (NET0004), which should not be exposed to an external I2C device, and the LM1117 output has only a 100 nF stability capacitor; these are the deviations from sound design practice."
}

